import React, { useState } from 'react';
import logo from '../../../assets/logo.png';

function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  return (
    <header className="bg-[#FDF8F3] border-b border-[#E1D5C9] p-4">
      <div className="flex items-center justify-between flex-wrap md:flex-nowrap">
        {/* Logo */}
        <img src={logo} alt="Logo" className="h-12" />

        {/* Mobile Menu Toggle */}
        <div className="ml-auto md:hidden">
          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="text-2xl font-bold"
          >
            ☰
          </button>
        </div>

        {/* Nav + Button Container */}
        <div
          className={`w-full md:w-auto ${
            isMenuOpen ? 'flex' : 'hidden'
          } flex-col items-center mt-4 md:mt-0 md:flex md:flex-row md:justify-center md:items-center md:gap-6`}
        >
          {/* Nav Links */}
          <nav className="flex flex-col items-center gap-3 md:flex-row md:gap-6 text-[clamp(0.9rem,2vw,1.1rem)] font-semibold">
            <a href="#" className="text-[#f48f0f]">Home</a>
            <a href="#" className="text-[#292929]">About</a>
            <a href="#" className="text-[#292929]">Gallery</a>
            <a href="#" className="text-[#292929]">Education</a>
          </nav>

          {/* Button */}
          <div className="mt-4 md:mt-0 md:ml-6">
            <button className="bg-[#F48F0F] text-[#292929] px-4 py-2 rounded-full font-semibold text-[clamp(0.9rem,2vw,1rem)]">
              Become a member
            </button>
          </div>
        </div>
      </div>
    </header>
  );
}

export default Navbar;
